// Room: D-pad run, C jump, B slash (UP + B upward), DOWN crouch, DOWN + C drop, START = floor map.
// Map:  START back, A run/stop the Void, B show everything (debug), C new floor.

enum { MODE_ROOM, MODE_MAP };

#define MAP_X 2
#define MAP_Y 4

static Level lv;
static Player player;
static u8 mode = MODE_ROOM;
static u8 depth = 1;
static bool showSecrets = FALSE;
static u16 deathFrames;      // > 0 while the death message is shown

// ---------------------------------------------------------------- floor map

static const char LETTER[] = { ' ', '.', 'S', 'B', 'U', '$', '?', '!' };


static void drawCell(u8 x, u8 y)
{
    u8 t = lv.floor.type[y][x];
    u8 secret = t == ROOM_SECRET || t == ROOM_SUPER_SECRET;
    if (t == ROOM_NONE || (secret && !showSecrets && !lv.visited[y][x])) return;

    // Like Isaac: visited rooms are known, rooms behind a visible door of a visited room are guessed.
    u8 known = showSecrets || lv.visited[y][x];
    u8 guessed = (x > 0 && lv.visited[y][x - 1] && (level_doors(&lv, x - 1, y) & DOOR_RIGHT))
        || (x < FLOOR_W - 1 && lv.visited[y][x + 1] && (level_doors(&lv, x + 1, y) & DOOR_LEFT))
        || (y > 0 && lv.visited[y - 1][x] && (level_doors(&lv, x, y - 1) & DOOR_DOWN))
        || (y < FLOOR_H - 1 && lv.visited[y + 1][x] && (level_doors(&lv, x, y + 1) & DOOR_UP));
    if (!known && !guessed) return;

    u16 px = MAP_X + x * 4, py = MAP_Y + y * 3;
    u16 pal = PAL0;
    if (t == ROOM_BOSS) pal = PAL1;
    else if (t >= ROOM_UPGRADE) pal = PAL2;
    if (!secret && level_cellInVoid(&lv, x, y)) pal = PAL3;

    char cell[4] = { '[', known ? LETTER[t] : ' ', ']', 0 };
    if (x == lv.cellX && y == lv.cellY) cell[1] = '@';
    VDP_setTextPalette(pal);
    VDP_drawText(cell, px, py);

    // Doors are drawn by the room on their left/top side only.
    u8 doors = level_doors(&lv, x, y), hidden = showSecrets ? lv.floor.hidden[y][x] & ~lv.opened[y][x] : 0;
    if (!known)   // only the doors leading back to visited rooms
    {
        if (!(x < FLOOR_W - 1 && lv.visited[y][x + 1])) doors &= ~DOOR_RIGHT;
        if (!(y < FLOOR_H - 1 && lv.visited[y + 1][x])) doors &= ~DOOR_DOWN;
    }
    VDP_setTextPalette(PAL0);
    if (doors & DOOR_RIGHT) VDP_drawText("-", px + 3, py);
    if (doors & DOOR_DOWN) VDP_drawText("|", px + 1, py + 1);
    VDP_setTextPalette(PAL2);
    if (hidden & DOOR_RIGHT) VDP_drawText("=", px + 3, py);
    if (hidden & DOOR_DOWN) VDP_drawText(":", px + 1, py + 1);
}

static void drawMapStatus(void)
{
    char line[41];
    VDP_setTextPalette(PAL0);
    sprintf(line, "GRAINE %04X  ETAGE %u  SALLES %u   ", lv.floor.seed, depth, lv.floor.roomCount);
    VDP_drawText(line, 2, 2);
    sprintf(line, "NEANT R=%4u %s   ", (u16) (lv.voidRadiusFx >> 8), lv.voidRunning ? "AVANCE" : "ARRET ");
    VDP_drawText(line, 2, 27);
}

static void drawMap(void)
{
    VDP_clearPlane(BG_A, TRUE);
    VDP_clearPlane(BG_B, TRUE);
    VDP_setTextPalette(PAL0);
    VDP_drawText("CARTE  START retour", 2, 0);
    VDP_drawText("A neant  B tout voir  C nouvel etage", 2, 1);
    for (u8 y = 0; y < FLOOR_H; y++)
        for (u8 x = 0; x < FLOOR_W; x++) drawCell(x, y);
    drawMapStatus();
}

static void newFloor(u16 seed)
{
    level_start(&lv, &player, seed, depth);
}

static void updateMap(u16 pressed)
{
    if (pressed & BUTTON_C)
    {
        depth = depth % 6 + 1;
        newFloor(random() ^ vtimer);
        drawMap();
    }
    if (pressed & BUTTON_B)
    {
        showSecrets = !showSecrets;
        drawMap();
    }
    if (pressed & BUTTON_A)
    {
        lv.voidRunning = !lv.voidRunning && lv.voidRadiusFx;
        drawMapStatus();
    }
}

// ---------------------------------------------------------------- room

// Camera: the room is streamed into a 64 x 32 tile plane that wraps around. Only the visible
// 41 x 29 tiles must be valid, so each step of one tile redraws one column or one row.
static s16 camX, camY;          // top-left of the screen, room pixels
static s16 drawnTX, drawnTY;    // camera tile the plane currently matches

// The Void circle on screen: for each visible row, the room columns inside the circle form one
// interval [in0, in1). One square root per row gives it, so the edge costs almost nothing and only
// the tiles crossing it are rewritten. Inside: high priority (normal). Outside: low priority, which
// the shadow/highlight mode draws at half brightness: the castle is seen through the Void, darkened.
static s16 rowRoomY[32];          // room row currently held by each plane row
static s16 rowIn0[32], rowIn1[32];

static u16 isqrt32(u32 v)
{
    u16 lo = 0, hi = 0xFFFF;
    while (lo < hi)
    {
        u16 mid = lo + (hi - lo + 1) / 2;
        if ((u32) mid * mid <= v) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

static void rowInterval(s16 ty, s16 *in0, s16 *in1)
{
    s16 r = lv.voidRadiusFx >> 8;
    s16 wy = lv.cellY * CELL_H_PX + ty * 8 + 4 - lv.voidCY;
    if (wy > r || -wy > r)
    {
        *in0 = *in1 = 0;
        return;
    }
    s16 half = isqrt32((u32) r * r - (u32) ((s32) wy * wy));
    s16 cx = lv.voidCX - lv.cellX * CELL_W_PX;   // circle centre in room pixels
    *in0 = (cx - half - 4 + 7) >> 3;             // first tile whose centre is inside
    *in1 = ((cx + half - 4) >> 3) + 1;
}
static u8 roomTile(s16 tx, s16 ty)
{
    if (tx < 0 || ty < 0 || tx >= lv.room.w || ty >= lv.room.h) return TILE_SOLID;   // walls go on
    return lv.room.tiles[ty][tx];
}

// Castle tile for a room cell: stone picks its variant from the open sides (sunlit top, shaded
// underside, lit left face...), planks from their neighbours. Index into the castle tileset.
static u16 castleTile(s16 tx, s16 ty)
{
    u8 t = roomTile(tx, ty);
    if (t == TILE_PLATFORM)
    {
        u8 l = roomTile(tx - 1, ty) == TILE_PLATFORM, r = roomTile(tx + 1, ty) == TILE_PLATFORM;
        return CASTLE_PLANK + (l && r ? 2 : l ? 3 : r ? 1 : 0);
    }
    if (t != TILE_SOLID) return 0;
    u8 parity = (tx + ty) & 1;   // bricks span two tiles
    if (lv.crackedCount && level_crackedAt(&lv, tx * 8 + 4, ty * 8 + 4)) return CASTLE_CRACKED + parity;
    u8 mask = (roomTile(tx, ty - 1) != TILE_SOLID) | (roomTile(tx, ty + 1) != TILE_SOLID) << 1
        | (roomTile(tx - 1, ty) != TILE_SOLID) << 2 | (roomTile(tx + 1, ty) != TILE_SOLID) << 3;
    return CASTLE_STONE + parity * 16 + mask;
}

static void drawTileState(s16 tx, s16 ty, u8 inVoid)
{
    u16 index = (tx >= 0 && ty >= 0 && tx < lv.room.w && ty < lv.room.h) ? castleTile(tx, ty) : 0;
    VDP_setTileMapXY(BG_A, TILE_ATTR_FULL(PAL0, !inVoid, 0, 0, index ? GFX_CASTLE + index : 0), tx & 63, ty & 31);
}

static void drawColumn(s16 tx)
{
    for (s16 ty = drawnTY; ty <= drawnTY + SCREEN_H_TILES; ty++)
    {
        u8 cy = ty & 31;
        drawTileState(tx, ty, tx < rowIn0[cy] || tx >= rowIn1[cy]);
    }
}

static void drawRow(s16 ty)
{
    u8 cy = ty & 31;
    rowInterval(ty, &rowIn0[cy], &rowIn1[cy]);
    rowRoomY[cy] = ty;
    for (s16 tx = drawnTX; tx <= drawnTX + SCREEN_W_TILES; tx++)
        drawTileState(tx, ty, tx < rowIn0[cy] || tx >= rowIn1[cy]);
}
static void updateCamera(void)
{
    // Dead zone: the camera only moves when the ninja leaves a box around the screen centre.
    s16 px = player.x >> 8, py = player.y >> 8;
    if (px < camX + 144) camX = px - 144;
    if (px > camX + 176) camX = px - 176;
    if (py < camY + 96) camY = py - 96;
    if (py > camY + 160) camY = py - 160;

    s16 maxX = lv.room.w * ROOM_TILE - SCREEN_W_TILES * ROOM_TILE;
    s16 maxY = lv.room.h * ROOM_TILE - SCREEN_H_TILES * ROOM_TILE;
    if (camX > maxX) camX = maxX;
    if (camY > maxY) camY = maxY;
    if (camX < 0) camX = 0;
    if (camY < 0) camY = 0;
}

static void scrollCamera(void)
{
    s16 tx = camX >> 3, ty = camY >> 3;
    while (drawnTX < tx) { drawnTX++; drawColumn(drawnTX + SCREEN_W_TILES); }
    while (drawnTX > tx) { drawnTX--; drawColumn(drawnTX); }
    while (drawnTY < ty) { drawnTY++; drawRow(drawnTY + SCREEN_H_TILES); }
    while (drawnTY > ty) { drawnTY--; drawRow(drawnTY); }
    VDP_setHorizontalScroll(BG_A, -camX);
    VDP_setVerticalScroll(BG_A, camY);
    // Parallax: the far sky and ramparts drift at a quarter of the room's speed.
    VDP_setHorizontalScroll(BG_B, -((lv.cellX * CELL_W_PX + camX) >> 2));
    VDP_setVerticalScroll(BG_B, 8 + (camY >> 3));
}

// Each frame: new interval per visible row, rewrite only the columns between the old and new edges.
static void rewriteSpan(s16 ty, s16 a, s16 b, s16 in0, s16 in1)
{
    if (a > b) { s16 t = a; a = b; b = t; }
    if (a < drawnTX) a = drawnTX;
    if (b > drawnTX + SCREEN_W_TILES + 1) b = drawnTX + SCREEN_W_TILES + 1;
    for (s16 tx = a; tx < b; tx++) drawTileState(tx, ty, tx < in0 || tx >= in1);
}

static void refreshVoid(void)
{
    for (s16 ty = drawnTY; ty <= drawnTY + SCREEN_H_TILES; ty++)
    {
        u8 cy = ty & 31;
        s16 in0, in1;
        rowInterval(ty, &in0, &in1);
        if (in0 == rowIn0[cy] && in1 == rowIn1[cy]) continue;
        if (in0 >= in1 || rowIn0[cy] >= rowIn1[cy])
            rewriteSpan(ty, rowIn0[cy] < rowIn1[cy] ? rowIn0[cy] : in0, rowIn0[cy] < rowIn1[cy] ? rowIn1[cy] : in1, in0, in1);
        else
        {
            rewriteSpan(ty, rowIn0[cy], in0, in0, in1);
            rewriteSpan(ty, rowIn1[cy], in1, in0, in1);
        }
        rowIn0[cy] = in0;
        rowIn1[cy] = in1;
    }
}
static void drawRoom(void)
{
    updateCamera();
    drawnTX = camX >> 3;
    drawnTY = camY >> 3;
    for (s16 ty = drawnTY; ty <= drawnTY + SCREEN_H_TILES; ty++) drawRow(ty);
    scrollCamera();
}

// Sprites: 0 ninja, 1 slash, 2.. enemies (boss top), then boss bottom, shots, gem.
#define SPRITE_BOSS_LOW (2 + MAX_ENEMIES)
#define SPRITE_SHOTS (SPRITE_BOSS_LOW + 1)
#define SPRITE_GEM (SPRITE_SHOTS + MAX_SHOTS)
#define SPRITE_ITEM (SPRITE_GEM + 1)
#define SPRITE_PROPS (SPRITE_ITEM + 1)
#define SPRITE_PICKUPS (SPRITE_PROPS + MAX_PROPS)
#define SPRITE_COUNT (SPRITE_PICKUPS + MAX_PICKUPS)

// Animation frame from the player's state. Running advances one frame every 6 px travelled,
// so the legs match the ground speed (and the upgrades that change it).
static u8 ninjaFrame(void)
{
    static u16 runDistance;
    static u8 runFrame;
    if (player.hurtTimer) return NINJA_HURT;
    if (player.attackTimer) return NINJA_SLASH0 + player_attackPhase(&player);
    if (player.crouching) return NINJA_CROUCH;
    if (!player.onGround) return player.vy < -320 ? NINJA_RISE : player.vy > 320 ? NINJA_FALL : NINJA_PEAK;
    s16 speed = player.vx < 0 ? -player.vx : player.vx;
    if (speed < 96)
    {
        runDistance = 0;
        return NINJA_IDLE0 + ((vtimer >> 4) & 3);
    }
    runDistance += speed;   // no division in the frame loop: step the frame every 6 px
    while (runDistance >= 6 * 256)
    {
        runDistance -= 6 * 256;
        runFrame = (runFrame + 1) & 7;
    }
    return NINJA_RUN0 + runFrame;
}

static void drawSprites(void)
{
    s16 px = (player.x >> 8) - camX, py = (player.y >> 8) - camY;
    u16 flip = player.facingLeft;
    u16 frame = GFX_NINJA + ninjaFrame() * 12;
    // Sprite 0: ninja (24 x 32, body centred on x 12, feet on row GFX_FEET_ROW); blinks while invulnerable.
    s16 ny = (player.invulnerable & 4) ? -64 : py - GFX_FEET_ROW - 1;
    VDP_setSpriteFull(0, px - 12, ny, SPRITE_SIZE(3, 4), TILE_ATTR_FULL(PAL1, 1, 0, flip, frame), 1);

    // Sprite 1: slash, hidden off-screen when inactive.
    s16 top = py - (player.crouching ? PLAYER_CROUCH_H : PLAYER_H);
    s16 sx, sy;
    u16 size, tiles;
    if (player.attackDir == ATTACK_UP)
    {
        sx = px - 8;
        sy = top - 20;   // the arc starts 1 px into its art
        size = SPRITE_SIZE(2, 3);
        tiles = GFX_TILE_SLASH_UP;
    }
    else if (player.attackDir == ATTACK_DOWN)
    {
        sx = px - 8;
        sy = py - 4;
        size = SPRITE_SIZE(2, 3);
        tiles = GFX_TILE_SLASH_DOWN;
    }
    else
    {
        sx = player.facingLeft ? px + 4 - 24 : px - 4;   // the arc starts 10 px into its art
        sy = py - (player.crouching ? 16 : 24);
        size = SPRITE_SIZE(3, 2);
        tiles = GFX_TILE_SLASH;
    }
    if (!player_attackActive(&player)) sy = -64;
    VDP_setSpriteFull(1, sx, sy, size, TILE_ATTR_FULL(PAL1, 1, 0, flip, tiles), 2);

    // Sprites 2..: enemies. Flashing when hurt, fast blinking while the death puff plays.
    s16 bossLowX = 0, bossLowY = -64;
    u16 bossLowAttr = 0;
    for (u8 i = 0; i < MAX_ENEMIES; i++)
    {
        const Enemy *e = &lv.enemies.e[i];
        u8 index = 2 + i;
        s16 ex = (e->x >> 8) - camX - 8, ey = -64;
        u16 attr = 0, esize = SPRITE_SIZE(2, 2);
        u8 hidden = e->type == ENEMY_NONE || (e->deathTimer && (e->deathTimer & 2)) || (e->hurtTimer & 2)
            || (e->type == ENEMY_BOSS && e->state == BOSS_DASH_WARN && (e->stateTimer & 4));
        if (!hidden)
        {
            u16 epal = e->voidForm ? PAL3 : PAL2;
            if (e->type == ENEMY_WALKER)
            {
                ey = (e->y >> 8) - camY - GFX_WALKER_FEET - 1;
                esize = SPRITE_SIZE(2, 3);
                attr = TILE_ATTR_FULL(epal, 1, 0, e->facingLeft, GFX_TILE_WALKER);
            }
            else if (e->type == ENEMY_FLYER)
            {
                ey = (e->y >> 8) - camY - GFX_FLYER_BOTTOM - 1;
                u16 wing = (e->timer >> 3) & 1 ? 4 : 0;
                attr = TILE_ATTR_FULL(epal, 1, 0, e->facingLeft, GFX_TILE_FLYER + wing);
            }
            else if (e->type == ENEMY_ARCHER || e->type == ENEMY_GUARD)
            {
                ey = (e->y >> 8) - camY - GFX_WALKER_FEET - 1;
                esize = SPRITE_SIZE(2, 3);
                attr = TILE_ATTR_FULL(epal, 1, 0, e->facingLeft, e->type == ENEMY_ARCHER ? GFX_TILE_ARCHER : GFX_TILE_GUARD);
            }
            else if (e->type == ENEMY_NINJA)
            {
                ey = (e->y >> 8) - camY - GFX_FEET_ROW - 1;
                esize = SPRITE_SIZE(2, 4);
                attr = TILE_ATTR_FULL(epal, 1, 0, e->facingLeft, GFX_TILE_ENINJA);
            }
            else if (e->type == ENEMY_JELLY)
            {
                ey = (e->y >> 8) - camY - 16;
                attr = TILE_ATTR_FULL(epal, 1, 0, e->facingLeft, GFX_TILE_JELLY);
            }
            else if (e->type == ENEMY_JELLY_SMALL)
            {
                ex = (e->x >> 8) - camX - 4;
                ey = (e->y >> 8) - camY - 7;
                esize = SPRITE_SIZE(1, 1);
                attr = TILE_ATTR_FULL(epal, 1, 0, e->facingLeft, GFX_TILE_JELLY_SMALL);
            }
            else
            {
                // 32 x 48 in two sprites: feet on pixel row 45 of the doubled walker art.
                ex = (e->x >> 8) - camX - 16;
                ey = (e->y >> 8) - camY - 46;
                esize = SPRITE_SIZE(4, 4);
                attr = TILE_ATTR_FULL(epal, 1, 0, e->facingLeft, GFX_TILE_BOSS_TOP);
                bossLowX = ex;
                bossLowY = ey + 32;
                bossLowAttr = TILE_ATTR_FULL(epal, 1, 0, e->facingLeft, GFX_TILE_BOSS_BOTTOM);
            }
        }
        VDP_setSpriteFull(index, ex, ey, esize, attr, index + 1);
    }
    VDP_setSpriteFull(SPRITE_BOSS_LOW, bossLowX, bossLowY, SPRITE_SIZE(4, 2), bossLowAttr, SPRITE_SHOTS);
    for (u8 i = 0; i < MAX_SHOTS; i++)
    {
        const Shot *sh = &lv.enemies.shots[i];
        s16 y = sh->active ? (sh->y >> 8) - camY - 4 : -64;
        u16 tile = sh->kind == SHOT_ARROW ? GFX_TILE_ARROW : sh->kind == SHOT_SHURIKEN ? GFX_TILE_SHURIKEN : GFX_TILE_SHOT;
        u16 spal = sh->kind == SHOT_SPORE ? PAL3 : PAL2;
        u16 hflip = sh->vx < 0, vflip = sh->kind == SHOT_SHURIKEN && (vtimer & 4);   // shurikens spin
        VDP_setSpriteFull(SPRITE_SHOTS + i, (sh->x >> 8) - camX - 4, y, SPRITE_SIZE(1, 1),
                          TILE_ATTR_FULL(spal, 1, vflip, hflip, tile), SPRITE_SHOTS + i + 1);
    }
    s16 gy = lv.gemActive ? (lv.gemY >> 8) - camY - 8 : -64;
    VDP_setSpriteFull(SPRITE_GEM, (lv.gemX >> 8) - camX - 4, gy, SPRITE_SIZE(1, 1),
                      TILE_ATTR_FULL(PAL3, 1, 0, 0, GFX_TILE_GEM), SPRITE_ITEM);

    // Item on its altar, bobbing gently.
    s16 bob = ((vtimer >> 3) & 7) < 4 ? 0 : 1;
    if (lv.itemId == ITEM_HEART)
        VDP_setSpriteFull(SPRITE_ITEM, lv.itemX - camX - 4, lv.itemY - camY - 12 - bob, SPRITE_SIZE(1, 1),
                          TILE_ATTR_FULL(PAL1, 1, 0, 0, GFX_TILE_HEART), 0);
    else
        VDP_setSpriteFull(SPRITE_ITEM, lv.itemX - camX - 8, lv.itemId ? lv.itemY - camY - 20 - bob : -64,
                          SPRITE_SIZE(2, 2), TILE_ATTR_FULL(PAL2, 1, 0, 0, GFX_TILE_RELIC), SPRITE_PROPS);

    for (u8 i = 0; i < MAX_PROPS; i++)
    {
        const Prop *pr = &lv.props[i];
        u8 chest = pr->type >= PROP_CHEST_BRONZE;
        u8 shown = i < lv.propCount && (pr->alive || chest);   // opened chests stay, open
        u16 frame = chest ? PROP_CHEST_BRONZE + (pr->type - PROP_CHEST_BRONZE) * 2 + !pr->alive : pr->type;
        u16 flicker = pr->type == PROP_CANDLE && ((vtimer >> 3) & 1);   // candle flame wavers
        VDP_setSpriteFull(SPRITE_PROPS + i, pr->x - camX - 8, shown ? pr->y - camY - 16 : -64, SPRITE_SIZE(2, 2),
                          TILE_ATTR_FULL(PAL2, 1, 0, flicker, GFX_PROPS + frame * 4), SPRITE_PROPS + i + 1);
    }    for (u8 i = 0; i < MAX_PICKUPS; i++)
    {
        const Pickup *pk = &lv.pickups[i];
        u8 index = SPRITE_PICKUPS + i, link = i + 1 < MAX_PICKUPS ? index + 1 : 0;
        s16 x = (pk->x >> 8) - camX, y = (pk->y >> 8) - camY;
        if (pk->type == PICKUP_COIN)
            VDP_setSpriteFull(index, x - 4, y - 7, SPRITE_SIZE(1, 1), TILE_ATTR_FULL(PAL2, 1, 0, (vtimer >> 3) & 1, GFX_TILE_COIN), link);
        else if (pk->type == PICKUP_HEART || (pk->type == PICKUP_ITEM && pk->itemId == ITEM_HEART))
            VDP_setSpriteFull(index, x - 4, y - 12, SPRITE_SIZE(1, 1), TILE_ATTR_FULL(PAL1, 1, 0, 0, GFX_TILE_HEART), link);
        else if (pk->type == PICKUP_ITEM)
            VDP_setSpriteFull(index, x - 8, y - 20, SPRITE_SIZE(2, 2), TILE_ATTR_FULL(PAL2, 1, 0, 0, GFX_TILE_RELIC), link);
        else VDP_setSpriteFull(index, 0, -64, SPRITE_SIZE(1, 1), 0, link);
    }
    VDP_updateSprites(SPRITE_COUNT, DMA_QUEUE);
}

static void hideSprites(void)
{
    for (u8 i = 0; i < SPRITE_COUNT; i++) VDP_setSpritePosition(i, 0, -64);
    VDP_updateSprites(SPRITE_COUNT, DMA_QUEUE);
}

// HUD on plane A (does not scroll): hearts and light bar top left, minimap of the rooms around
// top right. Each part is redrawn only when what it shows has changed.
static u8 hudHp = 0xFF, hudMaxHp = 0xFF, hudLight = 0xFF, hudCell = 0xFF, hudCorrupted = 0xFF;
static u16 hudCoins = 0xFFFF;
static u16 itemMessage;   // frames left showing the name of the item just taken

static void hudTile(u16 x, u16 y, u16 pal, u16 tile)
{
    VDP_setTileMapXY(WINDOW, TILE_ATTR_FULL(pal, 1, 0, 0, tile), x, y);
}

static void drawMinimap(void)
{
    // 5 x 3 rooms around the current one, Isaac-style: filled = here, outline = known.
    for (s8 dy = -1; dy <= 1; dy++)
        for (s8 dx = -2; dx <= 2; dx++)
        {
            s16 x = lv.cellX + dx, y = lv.cellY + dy;
            u16 tile = 0, pal = PAL0;
            if (x >= 0 && y >= 0 && x < FLOOR_W && y < FLOOR_H && lv.visited[y][x])
            {
                u8 t = lv.floor.type[y][x];
                tile = (dx == 0 && dy == 0) ? GFX_TILE_MAP_FILLED : GFX_TILE_MAP_OUTLINE;
                if (t == ROOM_BOSS) pal = PAL1;
                else if (t >= ROOM_UPGRADE) pal = PAL2;
                if (level_cellInVoid(&lv, x, y) && t != ROOM_SECRET && t != ROOM_SUPER_SECRET) pal = PAL3;
            }
            hudTile(36 + dx, 1 + dy, pal, tile);
        }
}

static void drawHud(void)
{
    if (player.hp != hudHp || player.maxHp != hudMaxHp)
    {
        hudHp = player.hp;
        hudMaxHp = player.maxHp;
        for (u8 i = 0; i < 12; i++)   // one heart = 2 hit points
        {
            u16 tile = 0;
            if (i * 2 < player.maxHp)
                tile = player.hp >= i * 2 + 2 ? GFX_TILE_HEART : player.hp == i * 2 + 1 ? GFX_TILE_HEART_HALF : GFX_TILE_HEART_EMPTY;
            hudTile(1 + i, 0, PAL1, tile);
        }
    }
    u8 steps = (u32) player.light * 10 / player.lightMax;
    if (steps != hudLight || player.corrupted != hudCorrupted)
    {
        hudLight = steps;
        for (u8 i = 0; i < 10; i++)
            hudTile(1 + i, 1, player.corrupted ? PAL3 : PAL2, i < steps ? GFX_TILE_LIGHT : GFX_TILE_LIGHT_EMPTY);
    }
    if (player.corrupted != hudCorrupted)
    {
        hudCorrupted = player.corrupted;
        gfx_setPlayerCorrupted(player.corrupted);
    }
    // Minimap: on a room change, and once a second for the Void colours.
    u8 cell = lv.cellY * FLOOR_W + lv.cellX;
    if (cell != hudCell || !(vtimer & 63))
    {
        hudCell = cell;
        drawMinimap();
    }
    if (player.coins != hudCoins)
    {
        char line[8];
        hudCoins = player.coins;
        hudTile(1, 2, PAL2, GFX_TILE_COIN);
        sprintf(line, "%u  ", player.coins);
        VDP_setTextPalette(PAL0);
        VDP_drawText(line, 2, 2);
    }
    // Shop price tags under the wares (the small shop room never scrolls).
    if (lv.shopChanged)
    {
        lv.shopChanged = 0;
        for (u8 i = 0; i < 3; i++)
        {
            const Pickup *pk = &lv.pickups[i];
            if (pk->type != PICKUP_ITEM) continue;
            char tag[4];
            sprintf(tag, "%u", pk->price);
            VDP_setTextPalette(player.coins >= pk->price ? PAL2 : PAL1);
            // On the room plane, in the air above the ware (the shop room never scrolls).
            VDP_drawTextBG(BG_A, tag, (pk->x >> 8) / 8 - (pk->price >= 10), (pk->y >> 8) / 8 - 4);
        }
    }
    if (itemMessage && --itemMessage == 0) VDP_clearTextArea(12, 2, 21, 1);
}

static void showText(const char *name)
{
    u16 len = 0;
    while (name[len]) len++;
    // Window row 2, between the coins and the minimap.
    VDP_clearTextArea(12, 2, 21, 1);
    VDP_setTextPalette(PAL0);
    VDP_drawText(name, 22 - len / 2, 2);
    itemMessage = IS_PAL_SYSTEM ? 100 : 120;
}

static void forceHud(void)
{
    hudHp = hudMaxHp = hudLight = hudCell = hudCorrupted = 0xFF;
    hudCoins = 0xFFFF;
    lv.shopChanged = 1;
}
#ifdef DEBUG_HUD
static void drawDebug(void)
{
    char line[41];
    VDP_setTextPalette(PAL0);
    sprintf(line, "X%4d Y%4d VX%5d VY%5d %c%c%c ", (s16) (player.x >> 8), (s16) (player.y >> 8),
            player.vx, player.vy, player.onGround ? 'G' : '-', player.crouching ? 'C' : '-',
            player_attackActive(&player) ? 'A' : '-');
    VDP_drawTextBG(BG_A, line, 1, 27);
}
#endif

// Room screen: sky on plane A (parallax), room on plane B (high priority), HUD in the window plane
// over the top 3 rows (the window replaces plane A there; the room still shows through).
static void enterRoom(void)
{
    mode = MODE_ROOM;
    VDP_setWindowVPos(FALSE, 3);
    VDP_setHilightShadow(TRUE);
    VDP_setTextPlane(WINDOW);
    VDP_clearPlane(WINDOW, TRUE);
    gfx_drawFar();
    drawRoom();
    forceHud();
    itemMessage = 0;
}

static void enterMap(void)
{
    mode = MODE_MAP;
    VDP_setWindowVPos(FALSE, 0);
    VDP_setHilightShadow(FALSE);
    VDP_setTextPlane(BG_A);
    VDP_setHorizontalScroll(BG_A, 0);
    VDP_setVerticalScroll(BG_A, 0);
    VDP_setHorizontalScroll(BG_B, 0);
    VDP_setVerticalScroll(BG_B, 0);
    hideSprites();
    drawMap();
}

// On the map the Void keeps closing (level_update only runs in rooms): shrink it here, and
// redraw the map once per second.
static void updateMapVoid(void)
{
    static u16 frames;
    if (lv.voidRunning)
    {
        lv.voidRadiusFx = lv.voidRadiusFx > lv.voidRate ? lv.voidRadiusFx - lv.voidRate : 0;
        if (!lv.voidRadiusFx) lv.voidRunning = 0;
    }
    if (++frames >= (IS_PAL_SYSTEM ? 50 : 60))
    {
        frames = 0;
        drawMap();
    }
}
// ---------------------------------------------------------------- main

static u16 readPad(void)
{
#ifdef DEBUG_SCRIPT
    // Frame-exact replay of tools/script.h; the game freezes when the script ends.
    static u16 step = 0, frame = 0;
    if (step >= sizeof(SCRIPT) / sizeof(SCRIPT[0]))
    {
        VDP_drawText("FIN DU SCRIPT", 26, 26);
        while (TRUE) SYS_doVBlankProcess();
    }
    u16 pad = SCRIPT[step][1];
    if (++frame >= SCRIPT[step][0])
    {
        step++;
        frame = 0;
    }
    return pad;
#else
    return JOY_readJoypad(JOY_1);
#endif
}

// Floor won (placeholder for the illustrated scene): the safe circle bursts open again and the
// world turns back to normal, then the gem screen, then the next floor.
static u8 gems, bossesInTime;
static u16 wonFrames;

// Big centred messages: the window plane covers the whole screen for a moment (the room on plane B
// still shows through its transparent pixels).
static void fullWindow(void)
{
    VDP_setWindowVPos(FALSE, 28);
    VDP_clearPlane(WINDOW, TRUE);
}

static void startFloorWon(void)
{
    wonFrames = 1;
    gems++;
    if (!lv.bossStrong) bossesInTime++;   // every boss reached in time: boss rush (later)
}

static void updateFloorWon(void)
{
    u16 grow = IS_PAL_SYSTEM ? 75 : 90, total = grow + (IS_PAL_SYSTEM ? 150 : 180);
    char line[41];
    wonFrames++;
    if (wonFrames <= grow)
    {
        lv.voidRadiusFx += (lv.voidStartFx - lv.voidRadiusFx) / 12 + (8 << 8);
        if (lv.voidRadiusFx > lv.voidStartFx) lv.voidRadiusFx = lv.voidStartFx;
        refreshVoid();
    }
    else if (wonFrames == grow + 1)
    {
        fullWindow();
        VDP_setTextPalette(PAL0);
        sprintf(line, "GEMME DE LA VIE  %u/7", gems);
        VDP_drawText(line, 10, 10);
        VDP_drawText("LE GARDIEN TE LEGUE UN POUVOIR", 5, 13);
        VDP_setTextPalette(lv.bossStrong ? PAL3 : PAL2);
        VDP_drawText(lv.bossStrong ? "LE NEANT L'AVAIT ATTEINT..." : "ARRIVE AVANT LE NEANT !", 7, 16);
    }
    else if (wonFrames >= total)
    {
        if (depth < 7) depth++;
        newFloor(random() ^ vtimer);   // health and upgrades are kept
        wonFrames = 0;
        enterRoom();
        return;
    }
    drawSprites();
}

static void updateRoom(u16 pad, u16 pressed)
{
    if (wonFrames)
    {
        updateFloorWon();
        return;
    }    if (deathFrames)
    {
        // Dead: the message stays two seconds, then a new floor starts.
        if (--deathFrames == 0)
        {
            player_init(&player, 0, 0);   // new run: full health, no upgrades
            depth = 1;
            newFloor(random() ^ vtimer);
            enterRoom();
        }
        return;
    }
    if (pressed & BUTTON_START)
    {
        enterMap();
        return;
    }
    player_update(&player, &lv.room, pad);
    u8 events = level_update(&lv, &player);
    if (events & LEVEL_REDRAW) drawRoom();
    if (events & LEVEL_ITEM) showText(player_itemName(lv.lastItem));
    if (events & LEVEL_MESSAGE) showText(lv.message == MSG_FULL_HEALTH ? "VIE PLEINE" : "PAS ASSEZ DE PIECES");
    if (events & LEVEL_GEM)
    {
        startFloorWon();
        return;
    }
    refreshVoid();
    updateCamera();
    scrollCamera();
    drawSprites();
    drawHud();
#ifdef DEBUG_HUD
    drawDebug();
#endif
    if (player.hp <= 0)
    {
        deathFrames = IS_PAL_SYSTEM ? 100 : 120;
        fullWindow();
        VDP_setTextPalette(PAL1);
        VDP_drawText("LE NEANT T'A EU...", 11, 13);
    }
}

int main(bool hardReset)
{
    (void) hardReset;
    VDP_setPlaneSize(64, 32, TRUE);
    VDP_setTextPriority(1);
    gfx_load();
    VDP_resetSprites();
    player_setRegion(IS_PAL_SYSTEM);
    enemies_setRegion(IS_PAL_SYSTEM);
    level_setRegion(IS_PAL_SYSTEM);

    player_init(&player, 0, 0);
    newFloor(0x1234);
    enterRoom();

    u16 prevPad = 0;
    while (TRUE)
    {
        u16 pad = readPad();
        u16 pressed = pad & ~prevPad;
        prevPad = pad;

        if (mode == MODE_ROOM) updateRoom(pad, pressed);
        else if (pressed & BUTTON_START) enterRoom();
        else
        {
            updateMap(pressed);
            updateMapVoid();
        }
        SYS_doVBlankProcess();
    }
    return 0;
}
